B.brf=new A.dQ("Questo evento \xe8 stato annullato da chi lo organizzava. Se avevi comprato un biglietto, il rimborso \xe8 gi\xe0 partito.",B.eA,B.bn,null)
B.bsB=new A.K(B.ez,B.brf,null)
